/**
 * Longest common subsequence of two line arrays, as the list of matched index
 * pairs. Ties are broken towards the earliest matches: a match is taken
 * whenever the current lines are equal, and otherwise the side whose remaining
 * subsequence is at least as long advances, the base winning a tie.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // suffix[i][j] = length of the LCS of base[i..] and side[j..]
  const suffix = []
  for (let i = 0; i <= n; i += 1) suffix.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = suffix[i]
    const next = suffix[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (suffix[i + 1][j] >= suffix[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * The stretches the common subsequence does not cover, each a run of base lines
 * replaced by a run of the side's lines. Bounds are half open.
 */
export function changes(base, side, label) {
  const matches = lcsMatches(base, side)
  const out = []
  let baseAt = 0
  let sideAt = 0
  const flush = (baseEnd, sideEnd) => {
    if (baseEnd > baseAt || sideEnd > sideAt) {
      out.push({ label, baseStart: baseAt, baseEnd, sideStart: sideAt, sideEnd })
    }
  }
  for (const [bi, si] of matches) {
    flush(bi, si)
    baseAt = bi + 1
    sideAt = si + 1
  }
  flush(base.length, side.length)
  return out
}

/** The changes of both sides, ordered by base start, mine before theirs. */
function orderedChanges(mine, base, theirs) {
  const all = [...changes(base, mine, 'mine'), ...changes(base, theirs, 'theirs')]
  return all
    .map((change, index) => ({ change, index }))
    .sort((a, b) => {
      if (a.change.baseStart !== b.change.baseStart) return a.change.baseStart - b.change.baseStart
      if (a.change.label !== b.change.label) return a.change.label === 'mine' ? -1 : 1
      return a.index - b.index
    })
    .map(entry => entry.change)
}

/** The lines a side contributes to a region spanning base[start, end). */
function sideLines(doc, base, own, start, end) {
  if (own.length === 0) return base.slice(start, end)
  let lo = Infinity
  let hi = -Infinity
  let firstBase = Infinity
  let lastBase = -Infinity
  for (const change of own) {
    if (change.sideStart < lo) lo = change.sideStart
    if (change.sideEnd > hi) hi = change.sideEnd
    if (change.baseStart < firstBase) firstBase = change.baseStart
    if (change.baseEnd > lastBase) lastBase = change.baseEnd
  }
  return doc.slice(lo - (firstBase - start), hi + (end - lastBase))
}

const same = (a, b) => a.length === b.length && a.every((line, index) => line === b[index])

/**
 * The regions of the merge, in base order: stable runs the merge keeps, runs a
 * single side changed, runs both sides changed the same way, and conflicts.
 */
export function regions(mine, base, theirs) {
  const ordered = orderedChanges(mine, base, theirs)
  const out = []
  let baseAt = 0
  let at = 0
  while (at < ordered.length) {
    const group = [ordered[at]]
    let start = ordered[at].baseStart
    let end = ordered[at].baseEnd
    at += 1
    while (at < ordered.length && ordered[at].baseStart <= end) {
      if (ordered[at].baseEnd > end) end = ordered[at].baseEnd
      group.push(ordered[at])
      at += 1
    }
    if (start > baseAt) out.push({ kind: 'stable', lines: base.slice(baseAt, start) })
    baseAt = end
    if (group.length === 1) {
      const only = group[0]
      const doc = only.label === 'mine' ? mine : theirs
      out.push({ kind: only.label, lines: doc.slice(only.sideStart, only.sideEnd) })
      continue
    }
    const mineLines = sideLines(mine, base, group.filter(c => c.label === 'mine'), start, end)
    const theirLines = sideLines(theirs, base, group.filter(c => c.label === 'theirs'), start, end)
    const baseLines = base.slice(start, end)
    if (same(mineLines, theirLines)) out.push({ kind: 'both', lines: mineLines })
    else if (same(mineLines, baseLines)) out.push({ kind: 'theirs', lines: theirLines })
    else if (same(theirLines, baseLines)) out.push({ kind: 'mine', lines: mineLines })
    else out.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirLines })
  }
  if (baseAt < base.length) out.push({ kind: 'stable', lines: base.slice(baseAt) })
  return out
