{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { regions } from './diff3.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Standard input as one string. */
function readStdin() {
  const chunks = []
  const fs = process.binding ? null : null
  void fs
  return new Promise((resolve, reject) => {
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

/** The three documents, as arrays of lines, or null when the input is malformed. */
function parse(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts.length === 3 ? parts : null
}

function render(mode, parts) {
  const [mine, base, theirs] = parts
  const out = []
  let conflicted = false
  for (const region of regions(mine, base, theirs)) {
    if (region.kind === 'conflict') {
      conflicted = true
      if (mode === 'regions') {
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
        continue
      }
      out.push('<<<<<<< mine', ...region.mine)
      if (mode === 'merge') out.push('||||||| base', ...region.base)
      out.push('=======', ...region.theirs, '>>>>>>> theirs')
      continue
    }
    if (mode === 'regions') out.push(`${region.kind} ${region.lines.length}`)
    else out.push(...region.lines)
  }
  return { text: out.map(line => `${line}\n`).join(''), code: conflicted ? 1 : 0 }
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || !MODES.includes(argv[0])) fail('usage: cli.js merge|merge2|regions')
const parts = parse(await readStdin())
if (parts === null) fail('expected three parts separated by %%%')
const { text, code } = render(argv[0], parts)
process.stdout.write(text)
process.exit(code)
"}

